machine_end_gcode:
;PRINT_END
================================================
; --- Start of conditional Z-axis movement ---
G90; Set positioning to absolute
{if max_layer_z < (max_print_height/2)}
; If the part is shorter than half the maximum height:
G1 Z{max_print_height / 2} F600 ; Move the bed to exactly half the Z-axis height
{else}
; If the part is taller than half the maximum height:
{if (max_layer_z + 4) <= max_print_height}
G1 Z{max_layer_z + 4} F600 ; Lower the bed by just 4mm
{else}
G1 Z{max_print_height} F600 ; Safety measure: lower the bed to the maximum physical limit to avoid collision
{endif}
{endif}
; --- End of conditional Z-axis movement ---
===============================================
